import React from 'react';
import LeftSlidebar from './leftSlidebar';
import axiosInstance from "../configurations/instance";

class EventCreationForm extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      eventName: '',
      eventType: '',
      eventDate: '',
      emailFields: [""],
      participants: [{ name: '', iin: '' }],
    };
  }

  handleInputChange = (field, value) => {
    this.setState({ [field]: value });
  };

  addEmailField = () => {
    this.setState(prevState => ({
      emailFields: [...prevState.emailFields, ""],
    }));
  };

  handleEmailChange = (index, event) => {
    const newEmailFields = [...this.state.emailFields];
    newEmailFields[index] = event.target.value;
    this.setState({ emailFields: newEmailFields });
  };

  addParticipant = () => {
    this.setState(prevState => ({
      participants: [...prevState.participants, { name: '', iin: '' }],
    }));
  };

  handleParticipantChange = (index, field, value) => {
    const newParticipants = [...this.state.participants];
    newParticipants[index][field] = value;
    this.setState({ participants: newParticipants });
  };

  handleSubmit = () => {
    const creatorEmail = localStorage.getItem('email'); 
  
    const { eventName, eventType, eventDate, emailFields, participants } = this.state;
  
    axiosInstance
      .post('/event/create-event', {
        eventName,
        eventType,
        eventDate,
        emailFields,
        participants,
        creatorEmail,
      })
      .then((response) => {
        console.log(response.data);
      })
      .catch((error) => {
        console.error('Error', error);
      });
  };
  

  render() {
    return (       <div className="creating-page">         <header className="main-header"></header>         <div className="page-main">            <LeftSlidebar/>            <div className="content">             <h1>Создание мероприятия</h1>             <div className="createForm">                <h3>Название мероприятия</h3>               <input type="text" placeholder="Напишите название мероприятия" />                <h3>Выберите тип мероприятия</h3>               <select>                 <option value="" disabled selected>Выберите тип мероприятия</option>                 <option value="seminar">Семинар</option>                 <option value="competition">Соревнования</option>                 <option value="conference">Конференция</option>               </select>                <h3>Дата проведения</h3>               <div><input type="datetime-local" className="datetime-input" /></div>                <h3>Добавьте проверяющего(-их)</h3>               <div>                 <input                    type="text"                    placeholder="Введите почту проверяющего"                    value={this.state.emailFields[0]}                    onChange={(e) => this.handleEmailChange(0, e)}                  />               </div>                {this.state.emailFields.slice(1).map((email, index) => (                 <div key={index + 1}>                   <input                      type="text"                      placeholder="Введите почту проверяющего"                      value={email}                      onChange={(e) => this.handleEmailChange(index + 1, e)}                    />                 </div>               ))}                <button type="button" onClick={this.addEmailField} >                 Добавить проверяющего               </button>                <h3>Добавьте участника(-ов)</h3>               {this.state.participants.map((participant, index) => (                 <div key={index}>                   <h4>Участник №{participant}</h4>                    <h3>ФИО</h3>                   <input                      type="text"                      placeholder="Введите ФИО участника"                    />                    <h3>ИИН</h3>                   <input                 type="number"                 placeholder="Введите ИИН участника"                 />                 </div>               ))}               <button type="button" onClick={this.addParticipant} >                 Добавить участника               </button>                <button type="button" className="add-button"> Создать </button>             </div>           </div>         </div>       </div>     );
  }
}

export default EventCreationForm;
